set rows [$block getRows]
set min_x 999999
set min_y 999999
set max_x -999999
set max_y -999999
foreach row $rows {
    set origin [$row getOrigin]
    set site [$row getSite]
    set site_width [expr [lindex $site 0]] # Site width?
    # Actually, we need the bounding box of the row.
    # The row has an origin and a length.
    set bbox [$row getBBox]
    if {[$bbox xMin] < $min_x} {set min_x [$bbox xMin]}
    if {[$bbox yMin] < $min_y} {set min_y [$bbox yMin]}
    if {[$bbox xMax] > $max_x} {set max_x [$bbox xMax]}
    if {[$bbox yMax] > $max_y} {set max_y [$bbox yMax]}
}
set core_area [list $min_x $min_y $max_x $max_y]

# Create the output directory if it doesn't exist
if {[file exists outputs] == 0} {
    file mkdir outputs
}

# Open the output file
set outfile [open outputs/io_ports.txt w]

# Get the list of top-level ports
# The format is typically: port_name direction width
set ports [report_ports]

foreach port_line $ports {
    # Split the line into components
    # Note: report_ports might return a list of lists or a string. 
    # In OpenROAD, report_ports usually returns a list of strings or a structured list.
    # Let's assume it returns a list of lists: {name direction width}

    # If report_ports returns a list of lists:
    set port_info [lindex $port_line 0]
    set port_name [lindex $port_info 0]
    set direction [lindex $port_info 1]
    set width [lindex $port_info 2]

    # Convert direction to lowercase for consistency
    set direction [string tolower $direction]

    if {$width > 1} {
        # Expand bus ports bit by bit
        for {set i 0} {$i < $width} {incr i} {
            puts $outfile "$port_name[$i] $direction"
        }
    } else {
        # Single bit port
        puts $outfile "$port_name $direction"
    }
}

close $outfile

# Get all top-level ports
set ports [get_ports]

set outfile [open outputs/io_ports.txt w]

foreach port $ports {
    set name [get_property $port name]
    set direction [get_property $port direction]

    # Direction might be "input", "output", or "inout"
    # Convert to lowercase
    set direction [string tolower $direction]

    # Check if the port is a bus by looking for '[' in the name
    # Or check if there's a width property
    set width [get_property $port width]

    if {$width > 1} {
        # Expand bus
        for {set i 0} {$i < $width} {incr i} {
            puts $outfile "$name[$i] $direction"
        }
    } else {
        # Single bit
        puts $outfile "$name $direction"
    }
}

close $outfile

set outfile [open outputs/io_ports.txt w]

# Get all top-level ports using wildcard pattern
set ports [get_ports *]

foreach port $ports {
    set name [get_property $port name]
    set direction [get_property $port direction]
    set direction [string tolower $direction]

    # Get width
    set width [get_property $port width]

    # If width is empty or 0, set to 1
    if {$width eq "" || $width == 0} {
        set width 1
    }

    if {$width > 1} {
        for {set i 0} {$i < $width} {incr i} {
            puts $outfile "$name[$i] $direction"
        }
    } else {
        puts $outfile "$name $direction"
    }
}

close $outfile

set outfile [open outputs/io_ports.txt w]

# Get all top-level ports
set ports [get_ports *]

foreach port $ports {
    set name [get_property $port name]
    set direction [get_property $port direction]
    set direction [string tolower $direction]

    # Check if the name contains '[' which indicates a bus
    if {[string match "*[*" $name]} {
        # Extract base name and range
        # Example: data[3:0] -> base: data, range: 3:0
        set base_name [string range $name 0 [expr [string first "[" $name] - 1]]]
        set range_part [string range $name [expr [string first "[" $name] + 1] end]
        # Remove the closing ']'
        set range_part [string trimright $range_part "]"]

        # Parse the range
        set msb [string range $range_part 0 [expr [string first ":" $range_part] - 1]]
        set lsb [string range $range_part [expr [string first ":" $range_part] + 1] end]

        # Determine direction of iteration
        if {$msb >= $lsb} {
            for {set i $lsb} {$i <= $msb} {incr i} {
                puts $outfile "$base_name[$i] $direction"
            }
        } else {
            for {set i $msb} {$i >= $lsb} {incr i} {
                puts $outfile "$base_name[$i] $direction"
            }
        }
    } else {
        # Single bit port
        puts $outfile "$name $direction"
    }
}

close $outfile

# Tcl script for OpenROAD to produce cell-usage summary

# Ensure output directory exists
file mkdir outputs

# Initialize an associative array to store cell counts
array set cell_counts {}
set total_count 0

# Get all instances in the design
# -hierarchical is needed to get instances within the top level
set instances [get_cells -hierarchical *]

foreach inst $instances {
    # Get the reference cell name (the type)
    set cell_type [get_property $inst ref_name]

    # Skip if cell_type is empty (should not happen for valid instances)
    if { $cell_type eq "" } {
        continue
    }

    # Check if the cell is a physical-only cell (tap, endcap, filler)
    # Patterns to exclude:
    # - Tap/Endcap: TAPCELL*, ENDCAP* (though ENDCAP might be part of TAPCELL or separate)
    # - Filler: FILLCELL*
    # Note: The platform doc mentions TAPCELL_X1 as tap/endcap. 
    # Filler cells are FILLCELL_X1 ... FILLCELL_X32.

    set is_excluded 0
    if { [string match -nocase "TAPCELL*" $cell_type] } {
        set is_excluded 1
    } elseif { [string match -nocase "ENDCAP*" $cell_type] } {
        set is_excluded 1
    } elseif { [string match -nocase "FILLCELL*" $cell_type] } {
        set is_excluded 1
    }

    # If not excluded, count it
    if { $is_excluded == 0 } {
        if { [info exists cell_counts($cell_type)] } {
            incr cell_counts($cell_type)
        } else {
            set cell_counts($cell_type) 1
        }
        incr total_count
    }
}

# Open the output file
set output_file "outputs/cell_usage.txt"
set fid [open $output_file w]

# Write each cell type and its count
# The order is not specified, so we can iterate the array. 
# However, array iteration order is not guaranteed. 
# The task says "any order".
foreach cell_type [array names cell_counts] {
    puts $fid "$cell_type $cell_counts($cell_type)"
}

# Write the total
puts $fid "total $total_count"

close $fid

define_pdn_grid -name "Core"
add_pdn_stripe -followpins -layer metal1 -extend_to_core_ring
add_pdn_stripe -layer metal4 -width 1.0 -pitch 5.0 -offset 2.5 -extend_to_core_ring
add_pdn_ring -grid "Core" -layers {metal5 metal6} -widths 2.0 -spacings 2.0 -core_offsets 2.0
add_pdn_connect -layers {metal5 metal6}
add_pdn_connect -layers {metal1 metal6}
add_pdn_connect -layers {metal1 metal4} -split_cuts {metal2 0.380} -ongrid {metal2 metal3}
add_pdn_connect -layers {metal4 metal5}
pdngen

set all_nets [get_nets]
set clk_net [get_nets -of [get_ports clk]]
set pg_nets {}
foreach port [get_ports] {
    set port_name [get_property $port name]
    if {$port_name eq "VDD" || $port_name eq "VSS" || $port_name eq "GND" || $port_name eq "vdd" || $port_name eq "vss" || $port_name eq "gnd"} {
        set net [get_nets -of [get_ports $port_name]]
        if {$net ne ""} {
            lappend pg_nets $net
        }
    }
}
set exclude_nets [concat $clk_net $pg_nets]

# Get all nets using wildcard pattern
set all_nets [get_nets *]

# Get clock net connected to the clk port
set clk_net [get_nets -of_objects [get_ports clk]]

# Get power/ground nets by checking port names
set pg_nets {}
foreach port [get_ports] {
    set port_name [get_property $port name]
    if {$port_name eq "VDD" || $port_name eq "VSS" || $port_name eq "GND" || $port_name eq "vdd" || $port_name eq "vss" || $port_name eq "gnd"} {
        set net [get_nets -of_objects [get_ports $port_name]]
        if {$net ne ""} {
            lappend pg_nets $net
        }
    }
}

# Exclude clock and power/ground nets
set fanout_nets {}
foreach net $all_nets {
    if {$net eq $clk_net} continue
    set is_pg 0
    foreach pg_net $pg_nets {
        if {$net eq $pg_net} {
            set is_pg 1
            break
        }
    }
    if {$is_pg} continue
    lappend fanout_nets $net
}

# Get fanout for each net and collect pairs
set net_fanout_pairs {}
foreach net $fanout_nets {
    set fanout_pins [get_fanout -from $net]
    set fanout_count [llength $fanout_pins]
    lappend net_fanout_pairs [list $net $fanout_count]
}

# Sort by fanout descending (second element of the list)
set sorted_nets [lsort -integer -decreasing -index 1 $net_fanout_pairs]

# Take top 5
set top5 [lrange $sorted_nets 0 4]

# Write to output file
set output_file "outputs/high_fanout_nets.txt"
set stream [open $output_file "w"]
foreach net_fanout $top5 {
    set net [lindex $net_fanout 0]
    set fanout [lindex $net_fanout 1]
    puts $stream "$net $fanout"
}
close $stream

# Get all nets using wildcard pattern
set all_nets [get_nets *]

# Get clock net connected to the clk port
# First, get the pin on the clk port, then get the net connected to that pin
set clk_pin [get_pins -of_objects [get_ports clk]]
if {$clk_pin ne ""} {
    set clk_net [get_nets -of_objects $clk_pin]
} else {
    set clk_net ""
}

# Get power/ground nets
set pg_nets {}
foreach port [get_ports] {
    set port_name [get_property $port name]
    if {$port_name eq "VDD" || $port_name eq "VSS" || $port_name eq "GND" || $port_name eq "vdd" || $port_name eq "vss" || $port_name eq "gnd"} {
        set pg_pin [get_pins -of_objects [get_ports $port_name]]
        if {$pg_pin ne ""} {
            set pg_net [get_nets -of_objects $pg_pin]
            if {$pg_net ne ""} {
                lappend pg_nets $pg_net
            }
        }
    }
}

# Exclude clock and power/ground nets
set fanout_nets {}
foreach net $all_nets {
    if {$net eq $clk_net} continue
    set is_pg 0
    foreach pg_net $pg_nets {
        if {$net eq $pg_net} {
            set is_pg 1
            break
