# Dictionary to map driver instance -> count of flop clock pins it drives
set driver_counts {}

# We also need to track which (driver_inst, flop_clock_pin) pairs we've already counted
# to avoid double counting if a driver drives multiple flops on the same net or different nets.
# Actually, since we iterate over unique flop clock pins, each pin is processed once.
# If a driver drives multiple flop clock pins, it will be encountered multiple times, which is correct.
# However, we need to make sure we don't count the same flop clock pin twice.
# Since `all_registers -clock_pins` returns unique pins, we are safe.

foreach cp $flop_clock_pins {
    # Get the net connected to this clock pin
    set nets [get_nets -of_objects [get_pins $cp]]

