    # There should be exactly one net for a clock pin
    set net_name [lindex $nets 0]

    # Find all output pins driving this net
    # get_pins -of_objects [get_nets $net_name] returns all pins connected to the net
    # We filter for output direction
    set driver_pins [get_pins -of_objects [get_nets $net_name] -filter {direction == output}]

    foreach dp $driver_pins {
        # Get the instance of this driver pin
        set cell_obj [get_cells $dp]
        if {[llength $cell_obj] == 0} {
