# Helper procedure to compute HPWL
proc compute_hpwl {} {
    set total_hpwl 0.0

    # Get all nets
    set nets [get_nets -hierarchical *]

    foreach net $nets {
        set net_name [get_full_name $net]

        # Skip power and ground nets
        if {[string match -nocase "*VDD*" $net_name] || [string match -nocase "*VSS*" $net_name] || 
            [string match -nocase "*vdd*" $net_name] || [string match -nocase "*vss*" $net_name]} {
            continue
        }

        # Get pins of the net
        set pins [get_pins -of_object $net]

        # Skip nets with fewer than 2 pins
        if {[llength $pins] < 2} {
            continue
        }

        # Get pin locations
        set min_x 1e9
        set max_x -1e9
        set min_y 1e9
        set max_y -1e9

        foreach pin $pins {
            # Get pin location using sta functions
            if {[sta::object_type $pin] == "Port"} {
                lassign [sta::port_location $pin] x y
            } else {
                lassign [sta::pin_location $pin] x y
            }

            if {$x < $min_x} {set min_x $x}
            if {$x > $max_x} {set max_x $x}
            if {$y < $min_y} {set min_y $y}
            if {$y > $max_y} {set max_y $y}
        }

        # Compute HPWL
        set width [expr {$max_x - $min_x}]
        set height [expr {$max_y - $min_y}]
        set hpwl [expr {$width + $height}]

        set total_hpwl [expr {$total_hpwl + $hpwl}]
    }

    return $total_hpwl
}

