set visited [list $root_net]
set queue [list $root_net]

# Traverse the clock tree to find all connected nets
while {[llength $queue] > 0} {
    set current_net [lindex $queue 0]
    set queue [lrange $queue 1 end]

    # Get all pins in the current net
    set pins [get_pins -of_objects [get_nets $current_net]]

    # Get fanout pins from these pins
    set fanout_pins [get_fanout $pins]

    # Get the nets connected to these fanout pins
    foreach fpin $fanout_pins {
        set fanout_net [get_net -of_objects $fpin]
        if {$fanout_net ni $visited} {
            lappend visited $fanout_net
            lappend clk_nets $fanout_net
