# Get all top-level ports of the current design
set ports [get_ports -of_objects $top_design]

foreach port $ports {
    set port_name [get_property $port NAME]
    set direction [get_property $port DIRECTION]

    # Check if it's a bus (multi-bit) by looking for '[' in the name
    if { [string match "*[*" $port_name] } {
        # It is a bus. We need to determine the width.
        # Extract the part inside brackets
        set full_name $port_name

        # Find the start and end of the bracketed part
        set start_bracket [string first "{" $full_name]
        if { $start_bracket == -1 } {
            set start_bracket [string first "[" $full_name]
        }
        set end_bracket [string last "}" $full_name]
        if { $end_bracket == -1 } {
            set end_bracket [string last "]" $full_name]
        }

        # Extract the range string
        set range_str [string range $full_name [expr {$start_bracket + 1}] [expr {$end_bracket - 1}]]

        # Parse the range. It could be [31:0] or [0] or [31]
        set parts [split $range_str :]
        set high [lindex $parts 0]
        set low [lindex $parts 1]

        # If only one part, it's a single bit, but we already checked for '['.
        # If it's a bus like data[0], low might be empty or same as high.
        if { [string length $low] == 0 } {
            set low $high
        }

        # Ensure numeric
        set high [expr {int($high)}]
        set low [expr {int($low)}]

        # Iterate from low to high
        for { set i $low } { $i <= $high } { incr i } {
            puts $fid "$port_name[$i] $direction"
        }

    } else {
        # Single bit port
        puts $fid "$port_name $direction"
    }
}

