set all_nets [get_nets *]

# Identify the clock net name
# Try to get the net named 'clk' directly
set clk_net ""
set clk_net_obj [get_nets clk]
if {[llength $clk_net_obj] > 0} {
    set clk_net [get_name [lindex $clk_net_obj 0]]
} else {
    # If not found, iterate through all nets to find the one connected to the clk port
    set clk_port [get_ports clk]
    if {[llength $clk_port] > 0} {
        set clk_port_name [get_name [lindex $clk_port 0]]
        foreach net $all_nets {
            set net_name [get_name $net]
            # Check if this net has a port terminal named clk
            set ports_on_net [get_ports -of_objects $net]
            if {[llength $ports_on_net] > 0} {
                foreach port $ports_on_net {
                    if {[get_name $port] eq $clk_port_name} {
                        set clk_net $net_name
                        break
                    }
                }
            }
            if {$clk_net ne ""} break
        }
    }
}

# Define a list to store {fanout net_name} pairs
set fanout_list {}

# Filter nets: exclude power/ground and clock nets
foreach net $all_nets {
    set net_name [get_name $net]

    # Skip empty names
    if {$net_name eq ""} continue

    # Skip power/ground nets (common patterns)
    if {[string match -nocase "*VDD*" $net_name] || \
        [string match -nocase "*VSS*" $net_name] || \
        [string match -nocase "*GND*" $net_name] || \
        [string match -nocase "*vdd*" $net_name] || \
        [string match -nocase "*vss*" $net_name] || \
        [string match -nocase "*gnd*" $net_name]} {
        continue
    }

    # Skip the clock net
    if {$clk_net ne "" && $net_name eq $clk_net} {
        continue
    }

    # Calculate fanout: number of sinks (load pins) on the net
    # get_fanout -from $net returns the pins driven by the net
    set fanout_pins [get_fanout -from $net]
    set fanout_count [llength $fanout_pins]

    lappend fanout_list [list $fanout_count $net_name]
}

# Sort the list by fanout descending
# Create a list of strings "fanout net_name" for sorting
set sort_list {}
foreach item $fanout_list {
    lappend sort_list [format "%06d %s" [lindex $item 0] [lindex $item 1]]
}

# Sort the list in reverse order (descending)
set sorted_list [lsort -reverse -dictionary $sort_list]

# Take the top 5
set top5 [lrange $sorted_list 0 4]

# Write the output
foreach item $top5 {
    # Parse back the fanout and net name
    # Format is "%06d %s". So first 6 chars are fanout, then space, then net name.
    set fanout_val [string trim [string range $item 0 5]]
    set net_name_val [string trim $item 6]

    puts $output_file "$net_name_val $fanout_val"
}

close $output_file

