proc calculate_hpwl {} {
    set total_hpwl 0
    set nets [get_nets -hierarchical]
    foreach net $nets {
        # Skip power and ground nets
        set net_name [get_property $net name]
        if {$net_name eq "VDD" || $net_name eq "VSS" || $net_name eq "gnd" || $net_name eq "vdd"} {
            continue
        }

        # Get pins of the net
        set pins [get_pins -hierarchical -of $net]
        if {[llength $pins] < 2} {
            continue
        }

        # Get locations of pins
        set min_x 1e9
        set max_x -1e9
        set min_y 1e9
        set max_y -1e9

        foreach pin $pins {
            # Get the instance of the pin
            set inst [get_property $pin instance]
            if {$inst eq ""} {
                # IO pin
                set pin_name [get_property $pin name]
                # Get location of IO pin
                # This is tricky. IO pins are on the boundary.
                # I need to get the bounding box of the pin shape.
                # Use dbGet or similar.
                # Let's try get_property
                set bbox [get_property $pin bbox]
                if {$bbox ne ""} {
                    # bbox is [x1 y1 x2 y2]
                    set x1 [lindex $bbox 0]
                    set y1 [lindex $bbox 1]
                    set x2 [lindex $bbox 2]
                    set y2 [lindex $bbox 3]
                    set cx [expr ($x1 + $x2) / 2.0]
                    set cy [expr ($y1 + $y2) / 2.0]
                } else {
                    # Skip if no bbox
                    continue
                }
            } else {
                # Standard cell pin
                set pin_name [get_property $pin name]
                # Get the location of the pin shape
                # This is also tricky.
                # I need to get the bounding box of the pin shape on the instance.
                # Let's try get_property $pin bbox
                set bbox [get_property $pin bbox]
                if {$bbox ne ""} {
                    set x1 [lindex $bbox 0]
                    set y1 [lindex $bbox 1]
                    set x2 [lindex $bbox 2]
                    set y2 [lindex $bbox 3]
                    set cx [expr ($x1 + $x2) / 2.0]
                    set cy [expr ($y1 + $y2) / 2.0]
                } else {
                    continue
                }
            }

            if {$cx < $min_x} { set min_x $cx }
            if {$cx > $max_x} { set max_x $cx }
            if {$cy < $min_y} { set min_y $cy }
            if {$cy > $max_y} { set max_y $cy }
        }

        if {$min_x == 1e9} {
            continue
        }

        set hpwl [expr ($max_x - $min_x) + ($max_y - $min_y)]
        set total_hpwl [expr $total_hpwl + $hpwl]
    }
    return $total_hpwl
}

