# Helper procedure to calculate HPWL
proc calculate_hpwl {} {
    set total_hpwl 0
    set nets [get_nets -hierarchical]
    foreach net $nets {
        set net_name [get_property $net name]
        # Skip power and ground nets
        if {$net_name eq "VDD" || $net_name eq "VSS" || $net_name eq "gnd" || $net_name eq "vdd"} {
            continue
        }

        set pins [get_pins -hierarchical -of $net]
        if {[llength $pins] < 2} {
            continue
        }

        set min_x 1e9
        set max_x -1e9
        set min_y 1e9
        set max_y -1e9
        set pin_count 0

        foreach pin $pins {
            # Get bounding box of the pin shape
            set bbox [dbGet $pin.bbox]
            if {$bbox eq ""} {
                continue
            }
            # bbox should be a list of 4 numbers: x1 y1 x2 y2
            if {[llength $bbox] != 4} {
                continue
            }
            set x1 [lindex $bbox 0]
            set y1 [lindex $bbox 1]
            set x2 [lindex $bbox 2]
            set y2 [lindex $bbox 3]
            set cx [expr ($x1 + $x2) / 2.0]
            set cy [expr ($y1 + $y2) / 2.0]

            if {$cx < $min_x} { set min_x $cx }
            if {$cx > $max_x} { set max_x $cx }
            if {$cy < $min_y} { set min_y $cy }
            if {$cy > $max_y} { set max_y $cy }
            incr pin_count
        }

        if {$pin_count < 2} {
            continue
        }

        set hpwl [expr ($max_x - $min_x) + ($max_y - $min_y)]
        set total_hpwl [expr $total_hpwl + $hpwl]
    }
    return $total_hpwl
}

